/* Procedural backgrounds; no external or personal image files. */
Night.wallpapers=(()=>{const scenes={home:'#123234',journal:'#103146',projects:'#3e251b',about:'#2e1740',contact:'#12362d',gallery:'#383019'};const layer=document.createElement('div');layer.id='route-wallpaper';layer.setAttribute('aria-hidden','true');document.body.prepend(layer);function mount(route){const page=Object.hasOwn(scenes,route)?route:route==='post'?'journal':'home';layer.style.background='radial-gradient(ellipse at 70% 30%, '+scenes[page]+', #05080f 75%)';layer.dataset.scene=page;document.documentElement.dataset.wallpaper=page;}mount(location.hash.split('/')[1]||'home');return{mount};})();
